INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-02','HSK2-02','HSK 2 · Đề 02','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-02-q01','seed-hsk2-02',1,'single_choice','Pinyin phù hợp với “知道” là phương án nào?','Pinyin của “知道” là “zhīdào”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q02','seed-hsk2-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “bởi vì”.','Từ phù hợp là “因为”, đọc là yīnwèi. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q03','seed-hsk2-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “一起 — yìqǐ”, nghĩa là “cùng nhau”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q04','seed-hsk2-02',4,'single_choice','Từ “觉得” gần nghĩa nhất với phương án nào?','“觉得” (juéde) có nghĩa là “cảm thấy”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q05','seed-hsk2-02',5,'single_choice','Pinyin phù hợp với “时间” là phương án nào?','Pinyin của “时间” là “shíjiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thời gian”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q06','seed-hsk2-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “vận động”.','Từ phù hợp là “运动”, đọc là yùndòng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q07','seed-hsk2-02',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “房间 — fángjiān”, nghĩa là “phòng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q08','seed-hsk2-02',8,'single_choice','Từ “告诉” gần nghĩa nhất với phương án nào?','“告诉” (gàosu) có nghĩa là “nói cho biết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-02-q09','seed-hsk2-02',9,'single_choice','Pinyin phù hợp với “所以” là phương án nào?','Pinyin của “所以” là “suǒyǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cho nên”.',NULL,NULL,0,1,'',datetime('now')),
