INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-03','HSK2-03','HSK 2 · Đề 03','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-03-q01','seed-hsk2-03',1,'single_choice','Pinyin phù hợp với “准备” là phương án nào?','Pinyin của “准备” là “zhǔnbèi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuẩn bị”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q02','seed-hsk2-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “hy vọng”.','Từ phù hợp là “希望”, đọc là xīwàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q03','seed-hsk2-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “开始 — kāishǐ”, nghĩa là “bắt đầu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q04','seed-hsk2-03',4,'single_choice','Từ “身体” gần nghĩa nhất với phương án nào?','“身体” (shēntǐ) có nghĩa là “cơ thể”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q05','seed-hsk2-03',5,'single_choice','Pinyin phù hợp với “旁边” là phương án nào?','Pinyin của “旁边” là “pángbiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bên cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q06','seed-hsk2-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “có thể”.','Từ phù hợp là “可能”, đọc là kěnéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q07','seed-hsk2-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “已经 — yǐjīng”, nghĩa là “đã”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q08','seed-hsk2-03',8,'single_choice','Từ “帮助” gần nghĩa nhất với phương án nào?','“帮助” (bāngzhù) có nghĩa là “giúp đỡ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q09','seed-hsk2-03',9,'single_choice','Pinyin phù hợp với “问题” là phương án nào?','Pinyin của “问题” là “wèntí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vấn đề”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q10','seed-hsk2-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “sự việc”.','Từ phù hợp là “事情”, đọc là shìqing. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q11','seed-hsk2-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “考试 — kǎoshì”, nghĩa là “kỳ thi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-03-q12','seed-hsk2-03',12,'single_choice','Từ “知道” gần nghĩa nhất với phương án nào?','“知道” (zhīdào) có nghĩa là “biết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
