('seed-hsk2-06-q31','seed-hsk2-06',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “房间 — fángjiān”, nghĩa là “phòng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-06-q32','seed-hsk2-06',32,'single_choice','Từ “告诉” gần nghĩa nhất với phương án nào?','“告诉” (gàosu) có nghĩa là “nói cho biết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
