INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-07','HSK2-07','HSK 2 · Đề 07','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 07 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-07-q01','seed-hsk2-07',1,'single_choice','Pinyin phù hợp với “运动” là phương án nào?','Pinyin của “运动” là “yùndòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vận động”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q02','seed-hsk2-07',2,'single_choice','Chọn từ Hán ngữ có nghĩa “phòng”.','Từ phù hợp là “房间”, đọc là fángjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q03','seed-hsk2-07',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “告诉 — gàosu”, nghĩa là “nói cho biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q04','seed-hsk2-07',4,'single_choice','Từ “所以” gần nghĩa nhất với phương án nào?','“所以” (suǒyǐ) có nghĩa là “cho nên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q05','seed-hsk2-07',5,'single_choice','Pinyin phù hợp với “准备” là phương án nào?','Pinyin của “准备” là “zhǔnbèi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuẩn bị”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q06','seed-hsk2-07',6,'single_choice','Chọn từ Hán ngữ có nghĩa “hy vọng”.','Từ phù hợp là “希望”, đọc là xīwàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q07','seed-hsk2-07',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “开始 — kāishǐ”, nghĩa là “bắt đầu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q08','seed-hsk2-07',8,'single_choice','Từ “身体” gần nghĩa nhất với phương án nào?','“身体” (shēntǐ) có nghĩa là “cơ thể”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q09','seed-hsk2-07',9,'single_choice','Pinyin phù hợp với “旁边” là phương án nào?','Pinyin của “旁边” là “pángbiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bên cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q10','seed-hsk2-07',10,'single_choice','Chọn từ Hán ngữ có nghĩa “có thể”.','Từ phù hợp là “可能”, đọc là kěnéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q11','seed-hsk2-07',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “已经 — yǐjīng”, nghĩa là “đã”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q12','seed-hsk2-07',12,'single_choice','Từ “帮助” gần nghĩa nhất với phương án nào?','“帮助” (bāngzhù) có nghĩa là “giúp đỡ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q13','seed-hsk2-07',13,'single_choice','Pinyin phù hợp với “问题” là phương án nào?','Pinyin của “问题” là “wèntí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vấn đề”.',NULL,NULL,0,1,'',datetime('now')),
