('seed-hsk2-07-q37','seed-hsk2-07',37,'single_choice','Pinyin phù hợp với “因为” là phương án nào?','Pinyin của “因为” là “yīnwèi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bởi vì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q38','seed-hsk2-07',38,'single_choice','Chọn từ Hán ngữ có nghĩa “cùng nhau”.','Từ phù hợp là “一起”, đọc là yìqǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q39','seed-hsk2-07',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “觉得 — juéde”, nghĩa là “cảm thấy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q40','seed-hsk2-07',40,'single_choice','Từ “时间” gần nghĩa nhất với phương án nào?','“时间” (shíjiān) có nghĩa là “thời gian”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q41','seed-hsk2-07',41,'single_choice','Pinyin phù hợp với “运动” là phương án nào?','Pinyin của “运动” là “yùndòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vận động”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q42','seed-hsk2-07',42,'single_choice','Chọn từ Hán ngữ có nghĩa “phòng”.','Từ phù hợp là “房间”, đọc là fángjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q43','seed-hsk2-07',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “告诉 — gàosu”, nghĩa là “nói cho biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q44','seed-hsk2-07',44,'single_choice','Từ “所以” gần nghĩa nhất với phương án nào?','“所以” (suǒyǐ) có nghĩa là “cho nên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q45','seed-hsk2-07',45,'single_choice','Pinyin phù hợp với “准备” là phương án nào?','Pinyin của “准备” là “zhǔnbèi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuẩn bị”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-07-q46','seed-hsk2-07',46,'single_choice','Chọn từ Hán ngữ có nghĩa “hy vọng”.','Từ phù hợp là “希望”, đọc là xīwàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
