INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-08','HSK2-08','HSK 2 · Đề 08','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-08-q01','seed-hsk2-08',1,'single_choice','Pinyin phù hợp với “可能” là phương án nào?','Pinyin của “可能” là “kěnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “có thể”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q02','seed-hsk2-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “đã”.','Từ phù hợp là “已经”, đọc là yǐjīng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q03','seed-hsk2-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “帮助 — bāngzhù”, nghĩa là “giúp đỡ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q04','seed-hsk2-08',4,'single_choice','Từ “问题” gần nghĩa nhất với phương án nào?','“问题” (wèntí) có nghĩa là “vấn đề”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q05','seed-hsk2-08',5,'single_choice','Pinyin phù hợp với “事情” là phương án nào?','Pinyin của “事情” là “shìqing”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sự việc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q06','seed-hsk2-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “kỳ thi”.','Từ phù hợp là “考试”, đọc là kǎoshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q07','seed-hsk2-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “知道 — zhīdào”, nghĩa là “biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q08','seed-hsk2-08',8,'single_choice','Từ “因为” gần nghĩa nhất với phương án nào?','“因为” (yīnwèi) có nghĩa là “bởi vì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q09','seed-hsk2-08',9,'single_choice','Pinyin phù hợp với “一起” là phương án nào?','Pinyin của “一起” là “yìqǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cùng nhau”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q10','seed-hsk2-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cảm thấy”.','Từ phù hợp là “觉得”, đọc là juéde. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q11','seed-hsk2-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “时间 — shíjiān”, nghĩa là “thời gian”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q12','seed-hsk2-08',12,'single_choice','Từ “运动” gần nghĩa nhất với phương án nào?','“运动” (yùndòng) có nghĩa là “vận động”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q13','seed-hsk2-08',13,'single_choice','Pinyin phù hợp với “房间” là phương án nào?','Pinyin của “房间” là “fángjiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phòng”.',NULL,NULL,0,1,'',datetime('now')),
