('seed-hsk2-08-q43','seed-hsk2-08',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “帮助 — bāngzhù”, nghĩa là “giúp đỡ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q44','seed-hsk2-08',44,'single_choice','Từ “问题” gần nghĩa nhất với phương án nào?','“问题” (wèntí) có nghĩa là “vấn đề”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q45','seed-hsk2-08',45,'single_choice','Pinyin phù hợp với “事情” là phương án nào?','Pinyin của “事情” là “shìqing”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sự việc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q46','seed-hsk2-08',46,'single_choice','Chọn từ Hán ngữ có nghĩa “kỳ thi”.','Từ phù hợp là “考试”, đọc là kǎoshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q47','seed-hsk2-08',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “知道 — zhīdào”, nghĩa là “biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q48','seed-hsk2-08',48,'single_choice','Từ “因为” gần nghĩa nhất với phương án nào?','“因为” (yīnwèi) có nghĩa là “bởi vì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q49','seed-hsk2-08',49,'single_choice','Pinyin phù hợp với “一起” là phương án nào?','Pinyin của “一起” là “yìqǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cùng nhau”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-08-q50','seed-hsk2-08',50,'single_choice','Chọn từ Hán ngữ có nghĩa “cảm thấy”.','Từ phù hợp là “觉得”, đọc là juéde. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
