('seed-hsk2-09-q49','seed-hsk2-09',49,'single_choice','Pinyin phù hợp với “开始” là phương án nào?','Pinyin của “开始” là “kāishǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bắt đầu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-09-q50','seed-hsk2-09',50,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ thể”.','Từ phù hợp là “身体”, đọc là shēntǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
