('seed-hsk2-11-q12','seed-hsk2-11',12,'single_choice','Từ “身体” gần nghĩa nhất với phương án nào?','“身体” (shēntǐ) có nghĩa là “cơ thể”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
