INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-12','HSK2-12','HSK 2 · Đề 12','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 12 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-12-q01','seed-hsk2-12',1,'single_choice','Pinyin phù hợp với “希望” là phương án nào?','Pinyin của “希望” là “xīwàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hy vọng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q02','seed-hsk2-12',2,'single_choice','Chọn từ Hán ngữ có nghĩa “bắt đầu”.','Từ phù hợp là “开始”, đọc là kāishǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q03','seed-hsk2-12',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “身体 — shēntǐ”, nghĩa là “cơ thể”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q04','seed-hsk2-12',4,'single_choice','Từ “旁边” gần nghĩa nhất với phương án nào?','“旁边” (pángbiān) có nghĩa là “bên cạnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q05','seed-hsk2-12',5,'single_choice','Pinyin phù hợp với “可能” là phương án nào?','Pinyin của “可能” là “kěnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “có thể”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q06','seed-hsk2-12',6,'single_choice','Chọn từ Hán ngữ có nghĩa “đã”.','Từ phù hợp là “已经”, đọc là yǐjīng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q07','seed-hsk2-12',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “帮助 — bāngzhù”, nghĩa là “giúp đỡ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q08','seed-hsk2-12',8,'single_choice','Từ “问题” gần nghĩa nhất với phương án nào?','“问题” (wèntí) có nghĩa là “vấn đề”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q09','seed-hsk2-12',9,'single_choice','Pinyin phù hợp với “事情” là phương án nào?','Pinyin của “事情” là “shìqing”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sự việc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q10','seed-hsk2-12',10,'single_choice','Chọn từ Hán ngữ có nghĩa “kỳ thi”.','Từ phù hợp là “考试”, đọc là kǎoshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q11','seed-hsk2-12',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “知道 — zhīdào”, nghĩa là “biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q12','seed-hsk2-12',12,'single_choice','Từ “因为” gần nghĩa nhất với phương án nào?','“因为” (yīnwèi) có nghĩa là “bởi vì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-12-q13','seed-hsk2-12',13,'single_choice','Pinyin phù hợp với “一起” là phương án nào?','Pinyin của “一起” là “yìqǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cùng nhau”.',NULL,NULL,0,1,'',datetime('now')),
