INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-13','HSK2-13','HSK 2 · Đề 13','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-13-q01','seed-hsk2-13',1,'single_choice','Pinyin phù hợp với “考试” là phương án nào?','Pinyin của “考试” là “kǎoshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kỳ thi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q02','seed-hsk2-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “biết”.','Từ phù hợp là “知道”, đọc là zhīdào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q03','seed-hsk2-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “因为 — yīnwèi”, nghĩa là “bởi vì”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q04','seed-hsk2-13',4,'single_choice','Từ “一起” gần nghĩa nhất với phương án nào?','“一起” (yìqǐ) có nghĩa là “cùng nhau”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q05','seed-hsk2-13',5,'single_choice','Pinyin phù hợp với “觉得” là phương án nào?','Pinyin của “觉得” là “juéde”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cảm thấy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q06','seed-hsk2-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thời gian”.','Từ phù hợp là “时间”, đọc là shíjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q07','seed-hsk2-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “运动 — yùndòng”, nghĩa là “vận động”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q08','seed-hsk2-13',8,'single_choice','Từ “房间” gần nghĩa nhất với phương án nào?','“房间” (fángjiān) có nghĩa là “phòng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q09','seed-hsk2-13',9,'single_choice','Pinyin phù hợp với “告诉” là phương án nào?','Pinyin của “告诉” là “gàosu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nói cho biết”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q10','seed-hsk2-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cho nên”.','Từ phù hợp là “所以”, đọc là suǒyǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q11','seed-hsk2-13',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “准备 — zhǔnbèi”, nghĩa là “chuẩn bị”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q12','seed-hsk2-13',12,'single_choice','Từ “希望” gần nghĩa nhất với phương án nào?','“希望” (xīwàng) có nghĩa là “hy vọng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q13','seed-hsk2-13',13,'single_choice','Pinyin phù hợp với “开始” là phương án nào?','Pinyin của “开始” là “kāishǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bắt đầu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q14','seed-hsk2-13',14,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ thể”.','Từ phù hợp là “身体”, đọc là shēntǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q15','seed-hsk2-13',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “旁边 — pángbiān”, nghĩa là “bên cạnh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-13-q16','seed-hsk2-13',16,'single_choice','Từ “可能” gần nghĩa nhất với phương án nào?','“可能” (kěnéng) có nghĩa là “có thể”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
