INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-15','HSK2-15','HSK 2 · Đề 15','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 15 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-15-q01','seed-hsk2-15',1,'single_choice','Pinyin phù hợp với “问题” là phương án nào?','Pinyin của “问题” là “wèntí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vấn đề”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q02','seed-hsk2-15',2,'single_choice','Chọn từ Hán ngữ có nghĩa “sự việc”.','Từ phù hợp là “事情”, đọc là shìqing. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q03','seed-hsk2-15',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “考试 — kǎoshì”, nghĩa là “kỳ thi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q04','seed-hsk2-15',4,'single_choice','Từ “知道” gần nghĩa nhất với phương án nào?','“知道” (zhīdào) có nghĩa là “biết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q05','seed-hsk2-15',5,'single_choice','Pinyin phù hợp với “因为” là phương án nào?','Pinyin của “因为” là “yīnwèi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bởi vì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q06','seed-hsk2-15',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cùng nhau”.','Từ phù hợp là “一起”, đọc là yìqǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q07','seed-hsk2-15',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “觉得 — juéde”, nghĩa là “cảm thấy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q08','seed-hsk2-15',8,'single_choice','Từ “时间” gần nghĩa nhất với phương án nào?','“时间” (shíjiān) có nghĩa là “thời gian”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q09','seed-hsk2-15',9,'single_choice','Pinyin phù hợp với “运动” là phương án nào?','Pinyin của “运动” là “yùndòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vận động”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q10','seed-hsk2-15',10,'single_choice','Chọn từ Hán ngữ có nghĩa “phòng”.','Từ phù hợp là “房间”, đọc là fángjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
