('seed-hsk2-15-q27','seed-hsk2-15',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “觉得 — juéde”, nghĩa là “cảm thấy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q28','seed-hsk2-15',28,'single_choice','Từ “时间” gần nghĩa nhất với phương án nào?','“时间” (shíjiān) có nghĩa là “thời gian”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q29','seed-hsk2-15',29,'single_choice','Pinyin phù hợp với “运动” là phương án nào?','Pinyin của “运动” là “yùndòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “vận động”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-15-q30','seed-hsk2-15',30,'single_choice','Chọn từ Hán ngữ có nghĩa “phòng”.','Từ phù hợp là “房间”, đọc là fángjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
