('seed-hsk2-16-q33','seed-hsk2-16',33,'single_choice','Pinyin phù hợp với “事情” là phương án nào?','Pinyin của “事情” là “shìqing”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sự việc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-16-q34','seed-hsk2-16',34,'single_choice','Chọn từ Hán ngữ có nghĩa “kỳ thi”.','Từ phù hợp là “考试”, đọc là kǎoshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-16-q35','seed-hsk2-16',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “知道 — zhīdào”, nghĩa là “biết”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-16-q36','seed-hsk2-16',36,'single_choice','Từ “因为” gần nghĩa nhất với phương án nào?','“因为” (yīnwèi) có nghĩa là “bởi vì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-16-q37','seed-hsk2-16',37,'single_choice','Pinyin phù hợp với “一起” là phương án nào?','Pinyin của “一起” là “yìqǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cùng nhau”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-16-q38','seed-hsk2-16',38,'single_choice','Chọn từ Hán ngữ có nghĩa “cảm thấy”.','Từ phù hợp là “觉得”, đọc là juéde. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
