('seed-hsk2-16-q40','seed-hsk2-16',40,'single_choice','Từ “运动” gần nghĩa nhất với phương án nào?','“运动” (yùndòng) có nghĩa là “vận động”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
