('seed-hsk2-17-q39','seed-hsk2-17',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “旁边 — pángbiān”, nghĩa là “bên cạnh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q40','seed-hsk2-17',40,'single_choice','Từ “可能” gần nghĩa nhất với phương án nào?','“可能” (kěnéng) có nghĩa là “có thể”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q41','seed-hsk2-17',41,'single_choice','Pinyin phù hợp với “已经” là phương án nào?','Pinyin của “已经” là “yǐjīng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đã”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q42','seed-hsk2-17',42,'single_choice','Chọn từ Hán ngữ có nghĩa “giúp đỡ”.','Từ phù hợp là “帮助”, đọc là bāngzhù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q43','seed-hsk2-17',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “问题 — wèntí”, nghĩa là “vấn đề”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q44','seed-hsk2-17',44,'single_choice','Từ “事情” gần nghĩa nhất với phương án nào?','“事情” (shìqing) có nghĩa là “sự việc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q45','seed-hsk2-17',45,'single_choice','Pinyin phù hợp với “考试” là phương án nào?','Pinyin của “考试” là “kǎoshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kỳ thi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q46','seed-hsk2-17',46,'single_choice','Chọn từ Hán ngữ có nghĩa “biết”.','Từ phù hợp là “知道”, đọc là zhīdào. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q47','seed-hsk2-17',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “因为 — yīnwèi”, nghĩa là “bởi vì”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q48','seed-hsk2-17',48,'single_choice','Từ “一起” gần nghĩa nhất với phương án nào?','“一起” (yìqǐ) có nghĩa là “cùng nhau”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q49','seed-hsk2-17',49,'single_choice','Pinyin phù hợp với “觉得” là phương án nào?','Pinyin của “觉得” là “juéde”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cảm thấy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-17-q50','seed-hsk2-17',50,'single_choice','Chọn từ Hán ngữ có nghĩa “thời gian”.','Từ phù hợp là “时间”, đọc là shíjiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
