INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk2-18','HSK2-18','HSK 2 · Đề 18','hsk','HSK 2',55,'published',1,'Đề luyện HSK 2 số 18 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk2-18-q01','seed-hsk2-18',1,'single_choice','Pinyin phù hợp với “时间” là phương án nào?','Pinyin của “时间” là “shíjiān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thời gian”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q02','seed-hsk2-18',2,'single_choice','Chọn từ Hán ngữ có nghĩa “vận động”.','Từ phù hợp là “运动”, đọc là yùndòng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q03','seed-hsk2-18',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “房间 — fángjiān”, nghĩa là “phòng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q04','seed-hsk2-18',4,'single_choice','Từ “告诉” gần nghĩa nhất với phương án nào?','“告诉” (gàosu) có nghĩa là “nói cho biết”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q05','seed-hsk2-18',5,'single_choice','Pinyin phù hợp với “所以” là phương án nào?','Pinyin của “所以” là “suǒyǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cho nên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q06','seed-hsk2-18',6,'single_choice','Chọn từ Hán ngữ có nghĩa “chuẩn bị”.','Từ phù hợp là “准备”, đọc là zhǔnbèi. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q07','seed-hsk2-18',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “希望 — xīwàng”, nghĩa là “hy vọng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q08','seed-hsk2-18',8,'single_choice','Từ “开始” gần nghĩa nhất với phương án nào?','“开始” (kāishǐ) có nghĩa là “bắt đầu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q09','seed-hsk2-18',9,'single_choice','Pinyin phù hợp với “身体” là phương án nào?','Pinyin của “身体” là “shēntǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ thể”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q10','seed-hsk2-18',10,'single_choice','Chọn từ Hán ngữ có nghĩa “bên cạnh”.','Từ phù hợp là “旁边”, đọc là pángbiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q11','seed-hsk2-18',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “可能 — kěnéng”, nghĩa là “có thể”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q12','seed-hsk2-18',12,'single_choice','Từ “已经” gần nghĩa nhất với phương án nào?','“已经” (yǐjīng) có nghĩa là “đã”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q13','seed-hsk2-18',13,'single_choice','Pinyin phù hợp với “帮助” là phương án nào?','Pinyin của “帮助” là “bāngzhù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giúp đỡ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q14','seed-hsk2-18',14,'single_choice','Chọn từ Hán ngữ có nghĩa “vấn đề”.','Từ phù hợp là “问题”, đọc là wèntí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
