('seed-hsk2-18-q45','seed-hsk2-18',45,'single_choice','Pinyin phù hợp với “所以” là phương án nào?','Pinyin của “所以” là “suǒyǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cho nên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q46','seed-hsk2-18',46,'single_choice','Chọn từ Hán ngữ có nghĩa “chuẩn bị”.','Từ phù hợp là “准备”, đọc là zhǔnbèi. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q47','seed-hsk2-18',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “希望 — xīwàng”, nghĩa là “hy vọng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q48','seed-hsk2-18',48,'single_choice','Từ “开始” gần nghĩa nhất với phương án nào?','“开始” (kāishǐ) có nghĩa là “bắt đầu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 2.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q49','seed-hsk2-18',49,'single_choice','Pinyin phù hợp với “身体” là phương án nào?','Pinyin của “身体” là “shēntǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ thể”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk2-18-q50','seed-hsk2-18',50,'single_choice','Chọn từ Hán ngữ có nghĩa “bên cạnh”.','Từ phù hợp là “旁边”, đọc là pángbiān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
